variables.scriptContent:
param(
    [string] [Parameter(Mandatory=$true)] $vaultName,
    [string] [Parameter(Mandatory=$true)] $certificateName,
    [string] [Parameter(Mandatory=$true)] $subjectName,
    [string] [Parameter(Mandatory=$true)] $certPwd,
    [string] [Parameter(Mandatory=$true)] $certDataString,
    [string] [Parameter(Mandatory=$true)] $certType
)

$ErrorActionPreference = 'Stop'
$DeploymentScriptOutputs = @{}

# Add verbose logging
Write-Host "Starting certificate deployment for: $certificateName"
Write-Host "Vault Name: $vaultName"
Write-Host "Certificate Type: $certType"

# Test Key Vault connectivity
try {
    Write-Host "Testing connectivity to Key Vault..."
    $vault = Get-AzKeyVault -VaultName $vaultName
    Write-Host "Successfully connected to Key Vault: $($vault.VaultName)"
} catch {
    Write-Error "Failed to connect to Key Vault '$vaultName': $($_.Exception.Message)"
    throw
}
if ($certType -eq 'selfsigned') 
{
    $policy = New-AzKeyVaultCertificatePolicy -SubjectName $subjectName -IssuerName Self -ValidityInMonths 12 -Verbose

    # private key is added as a secret that can be retrieved in the ARM template
    Add-AzKeyVaultCertificate -VaultName $vaultName -Name $certificateName -CertificatePolicy $policy -Verbose

    $newCert = Get-AzKeyVaultCertificate -VaultName $vaultName -Name $certificateName

    # Wait for KeyVault certificate creation to complete
    $tries = 0
    $maxTries = 180  # Increased timeout to 30 minutes
    do {
        Write-Host "Waiting for certificate creation completion... (attempt $tries/$maxTries)"
        Start-Sleep -Seconds 10
        
        try {
            $operation = Get-AzKeyVaultCertificateOperation -VaultName $vaultName -Name $certificateName
            Write-Host "Certificate operation status: $($operation.Status)"
            
            if ($operation.Status -eq 'failed') {
                $errorMsg = if ($operation.ErrorMessage) { $operation.ErrorMessage } else { "Unknown error" }
                throw "Creating certificate '$certificateName' in vault '$vaultName' failed with error: $errorMsg"
            }
        } catch {
            if ($_.Exception.Message -like "*not found*") {
                Write-Host "Certificate operation not found yet, continuing to wait..."
            } else {
                throw "Error checking certificate operation: $($_.Exception.Message)"
            }
        }
        
        $tries++
        
        if ($tries -gt $maxTries) {
            throw "Timed out waiting for creation of certificate '$certificateName' in vault '$vaultName' after $($maxTries * 10) seconds"
        }
    } while ($operation.Status -ne 'completed')		
}
else 
{
    Write-Host "Importing existing certificate from provided data..."
    try {
        $ss = ConvertTo-SecureString -String $certPwd -AsPlainText -Force
        $importResult = Import-AzKeyVaultCertificate -Name $certificateName -VaultName $vaultName -CertificateString $certDataString -Password $ss
        Write-Host "Successfully imported certificate: $($importResult.Name)"
    } catch {
        Write-Error "Failed to import certificate: $($_.Exception.Message)"
        throw
    }
}

Write-Host "Certificate deployment completed successfully for: $certificateName"
